// See https://blog.postman.com/2019/05/28/pro-tip-dynamically-unset-postman-environment-variables/
// for more details on what we're doing here. 

cleanupCollectionVariables();

function cleanupCollectionVariables() {
    const clean = _.keys(pm.collectionVariables.toObject());

    _.each(clean, (arrItem) => {
        pm.collectionVariables.unset(arrItem);
    });
}
